/// Metadata captured for every emitted signal.
#[derive(Debug, Clone, PartialEq)]
pub struct SignalMeta {
	/// Document-space pointer x, or `-1.0` for keyboard origin.
	pub x:           f64,
	/// Document-space pointer y, or `-1.0` for keyboard origin.
	pub y:           f64,
	/// Horizontal delta carried by the originating event.
	pub dx:          f64,
	/// Vertical delta carried by the originating event.
	pub dy:          f64,
	/// Horizontal drag displacement from the pointer-down origin.
	pub drag_dx:     f64,
	/// Vertical drag displacement from the pointer-down origin.
	pub drag_dy:     f64,
	/// Modifier bitset active at emission.
	pub mods:        u32,
	/// Pointer button code.
	pub button:      u32,
	/// Host-computed click count.
	pub clicks:      u32,
	/// Full key path of the signal-emitting node.
	pub key:         String,
	/// Full drag-source key for Drop, otherwise empty.
	pub src_key:     String,
	/// Innermost drag-source item key for `Drop`, otherwise empty.
	pub src_item:    String,
	/// Whether `DragEnd` represents abnormal termination.
	pub cancelled:   bool,
	/// Whether `DragEnd` delivered `Drop` to an eligible target.
	pub dropped:     bool,
	/// Deepest hit-target key on pointer-derived signals, otherwise empty.
	pub hit_key:     String,
	/// Pressed key name on keyboard-driven activation, otherwise empty.
	pub pressed_key: String,
}

impl From<&slab_kernel::dispatch::SigMeta> for SignalMeta {
	fn from(meta: &slab_kernel::dispatch::SigMeta) -> Self {
		Self {
			x:           meta.x,
			y:           meta.y,
			dx:          meta.dx,
			dy:          meta.dy,
			drag_dx:     meta.drag_dx,
			drag_dy:     meta.drag_dy,
			mods:        meta.mods,
			button:      meta.button,
			clicks:      meta.clicks,
			key:         meta.key.clone(),
			src_key:     meta.src_key.clone(),
			src_item:    meta.src_item.clone(),
			cancelled:   meta.cancelled,
			dropped:     meta.dropped,
			hit_key:     meta.hit_key.clone(),
			pressed_key: meta.pressed_key.clone(),
		}
	}
}

