	fn validate_menuitems(items: &[MenuItemsItem]) -> bool {
		let Ok(_) = i32::try_from(items.len()) else {
			return false;
		};
		let mut keys = std::collections::HashSet::with_capacity(items.len());
		for (index, item) in items.iter().enumerate() {
			let key = item.key.clone().unwrap_or_else(|| index.to_string());
			if key.is_empty() || !keys.insert(key) {
				return false;
			}
		}
		true
	}

	fn set_menuitems_path(
		&mut self,
		path: &str,
		items: &[MenuItemsItem],
		previous: Option<&[MenuItemsItem]>,
	) -> bool {
		let Ok(len) = i32::try_from(items.len()) else {
			return false;
		};
		if !kframe::inst_set_list_len(&mut self.inst, 2, path, len) {
			return false;
		}
		for (item_index, item) in items.iter().enumerate() {
			let previous = previous.and_then(|items| items.get(item_index));
			if previous == Some(item) {
				continue;
			}
			let Ok(index) = i32::try_from(item_index) else {
				return false;
			};
			if previous.is_none_or(|previous| previous.key != item.key) {
				let key = item.key.clone().unwrap_or_else(|| item_index.to_string());
				if !kframe::inst_set_list_key(&mut self.inst, 2, path, index, &key) {
					return false;
				}
			}
			if previous.is_none_or(|previous| previous.label != item.label) {
				let pv = ParamValue::Text(item.label.clone());
				if !kframe::inst_set_list_field(&mut self.inst, 2, path, index, "label", &pv) {
					return false;
				}
			}
			if previous.is_none_or(|previous| previous.enabled != item.enabled) {
				let pv = ParamValue::Bool(item.enabled);
				if !kframe::inst_set_list_field(&mut self.inst, 2, path, index, "enabled", &pv) {
					return false;
				}
			}
		}
		true
	}

	/// Reconciles list param `menu.items` and all nested lists with the last
	/// typed value.
	pub fn set_menu_items(&mut self, items: &[MenuItemsItem]) -> bool {
		if self.menu_items_cache.as_deref() == Some(items) {
			return true;
		}
		if !Self::validate_menuitems(items) {
			return false;
		}
		let previous = self.menu_items_cache.take();
		let updated = self.set_menuitems_path("", items, previous.as_deref());
		self.menu_items_cache = if updated {
			Some(items.to_vec())
		} else {
			previous
		};
		updated
	}

